                $add_target->($engine_target);
            } else {
                $add_target->("db:$engine:");
            }
        }
    }

    # Finally, check the core engine setting for the default target.
    my $core_engine = $config->get(key => 'core.engine');
    if (defined $core_engine && length $core_engine) {
        my $engine_target = $config->get(key => "engine.$core_engine.target");
        if (defined $engine_target && length $engine_target) {
            $add_target->($engine_target);
        } else {
            $add_target->("db:$core_engine:");
        }
    }

    # If no targets found at all, try to create the default target.
    if (!@targets) {
        my $target = eval { $class->new(%p) };
        push @targets, $target if $target;
    }

    return @targets;
}
